window.ME_DATA["y13-me"] = [
 {
  id:"l1", lesson:1, title:"ما الفساد؟ وأين يحدث؟", unit:"الوحدة الأولى: الأخلاق في حياتنا المعاصرة", art:"power",
  dna:"يقدّم مدير شركة لموظف حكومي ساعة فاخرة «عربونَ صداقة» قبل أسبوع واحد من اتخاذ الموظف قرارًا بشأن الشركة التي ستفوز بعقد كبير. اكتب: هل هذا فساد؟ وما الذي يجعل هذا التصرف صوابًا أو خطأً تحديدًا: الهدية نفسها، أم توقيتها، أم السلطة التي يملكها الموظف؟",
  dnaQs:["هل الساعة هدية أم رشوة؟ اذكر سببًا واحدًا.","ما الأهم هنا: الهدية نفسها، أم توقيتها، أم سلطة الموظف؟","اكتب تعريفك الخاص للفساد في جملة واحدة."],
  dnaHint:"تلاحظ الإجابة القوية أن التوقيت وسلطة الموظف في اتخاذ القرار يحوّلان «الهدية» إلى رشوة على الأرجح، إذ يتوقّع المدير مقابلًا لها. ويتضمّن التعريف الجيد ثلاثة عناصر: سلطة أُوكلت إلى شخص ما، وإساءة استخدام هذه السلطة، ومنفعة خاصة تعود على هذا الشخص أو على المقرّبين منه.",
  intentions:["أن أفهم الفساد بوصفه إساءة استخدام السلطة المؤتمنة لتحقيق مكاسب خاصة.","أن أميّز بين الأشكال الرئيسة للفساد، مثل الرشوة والاختلاس والمحسوبية وتضارب المصالح.","أن أحلّل أين يحدث الفساد في القطاعين العام والخاص، ولماذا تكون بعض القطاعات أكثر عرضة لمخاطره."],
  criteria:["أستطيع أن أعرّف الفساد تعريفًا دقيقًا، وأشرح كل عنصر من عناصر التعريف.","أستطيع أن أحدّد أربعة أشكال على الأقل من الفساد في حالات واقعية أو قريبة من الواقع، وأميّز بينها.","أستطيع أن أحلّل لماذا تكون بعض القطاعات ونقاط اتخاذ القرار أكثر عرضة لمخاطر الفساد."],
  concept:{key:"الأنظمة", related:"السلطة، المساءلة", soi:"يحدث الفساد حيثما أمكن إساءة استخدام السلطة المؤتمنة لتحقيق مكاسب خاصة؛ لذا فإن فهم أشكاله ومواضع حدوثه هو الخطوة الأولى نحو منعه.", context:"العدالة والتنمية: استكشاف كيفية إيكال السلطة واستخدامها وإساءة استخدامها داخل المؤسسات العامة والخاصة.", uae:"صادقت دولة الإمارات على اتفاقية الأمم المتحدة لمكافحة الفساد عام 2006، ويَعُدّ القانون الجزائي الاتحادي في الدولة الرشوة جريمة خطيرة؛ ويرتبط الموضوع بمادتَي السياسة العالمية (السلطة، الشرعية) وإدارة الأعمال (أخلاقيات الأعمال) في برنامج الدبلوما."},
  words:[["الفساد (Corruption)","إساءة استخدام السلطة المؤتمنة لتحقيق مكاسب خاصة (وهو التعريف الشائع الذي تعتمده منظمة الشفافية الدولية)."],["الرشوة (Bribery)","عرض شيء ذي قيمة أو تقديمه أو طلبه أو قبوله للتأثير في قرار ما بطريقة غير مشروعة."],["الاختلاس (Embezzlement)","سرقة أموال أو ممتلكات اؤتمن الشخص على إدارتها، أو إساءة استخدامها."],["المحسوبية (Nepotism)","تفضيل الأقارب أو الأصدقاء المقرّبين، في الوظائف أو العقود مثلًا، بصرف النظر عن الجدارة."],["تضارب المصالح (Conflict of interest)","موقف قد تؤثّر فيه المصالح الخاصة للشخص تأثيرًا غير مشروع في أداء واجباته المهنية."],["الابتزاز (Extortion)","الحصول على أموال أو امتيازات باستخدام التهديد أو إساءة استخدام السلطة."]],
  task1:{title:"مهمة البحث", mins:20, criterion:"المعيار B — البحث والاستقصاء", steps:["اختر شكلًا واحدًا من أشكال الفساد (الرشوة، أو الاختلاس، أو المحسوبية، أو تضارب المصالح، أو الابتزاز) وقطاعًا واحدًا يمكن أن يحدث فيه (مثل المشتريات الحكومية، أو الرعاية الصحية، أو الجمارك، أو الرياضة، أو البناء، أو التعليم).","ابحث فيه مستعينًا بمصدرين موثوقين على الأقل (مثل مكتب الأمم المتحدة المعني بالمخدرات والجريمة، أو منظمة الشفافية الدولية، أو منظمة التعاون الاقتصادي والتنمية، أو مؤسسات إخبارية موثوقة).","سجّل: كيف يحدث هذا الشكل من الفساد عادةً في ذلك القطاع، ومن المتضرّر منه.","حدّد ضمانة واحدة تستخدمها المؤسسات للحدّ من هذا الخطر، وقيّم مدى فاعليتها المتوقّعة."], prompts:["شكل الفساد والقطاع اللذان اخترتهما، ومصدراي","كيف يحدث هذا الشكل من الفساد عادةً في ذلك القطاع","من المتضرّر بشكل مباشر وغير مباشر","ضمانة واحدة، ومدى فاعليتها المتوقّعة"], success:"من الاختيارات الجيدة: الرشوة في المشتريات الحكومية (عقود كبيرة ونقاط قرار كثيرة)، أو تضارب المصالح في التوظيف، أو اختلاس أموال المشاريع، أو التلاعب بنتائج المباريات في الرياضة. تشرح الإجابات القوية آلية الفساد خطوة بخطوة (من يملك السلطة، وما الذي يُتبادل، وكيف يُخفى)، وتحدّد الضحايا غير المباشرين مثل دافعي الضرائب أو المنافسين النزيهين أو المرضى. وللوصول إلى أعلى مستوى، استخدم مصدرين موثوقين، وتجنّب الادعاءات المثيرة، وقيّم الضمانة تقييمًا ناقدًا، كأن تلاحظ أن إقرارات الذمة المالية لا تنجح إلا إذا راجعها أحد فعلًا."},
  task2:{title:"مهمة القراءة والكتابة", mins:25, criterion:"المعيار C — التواصل", extract:"يتعيّن على مديرة مشتريات في هيئة عامة متخيَّلة أن تختار مورّدًا لمشروع بناء مدرسة جديدة. فتمنح العقد لشركة يملكها زوج أختها، دون أن تُفصح عن هذه القرابة، مع أن عرض الشركة لم يكن الأرخص ولا الأعلى جودة. وعندما سُئلت قالت: «لم آخذ أي مال، لذلك لم أرتكب أي خطأ».", steps:["في فقرة تحليلية منظّمة (ادعاء، دليل، تحليل، استنتاج)، قيّم ما إذا كان سلوك المديرة يُعدّ فسادًا.","استخدم أربع كلمات على الأقل من بنك الكلمات استخدامًا دقيقًا (مثل الفساد، المحسوبية، تضارب المصالح، السلطة المؤتمنة).","رُدّ مباشرةً على دفاعها بأنها «لم تأخذ أي مال»، واختم بما كان ينبغي لها أن تفعله."], model:"إن سلوك المديرة حالة واضحة من الفساد، حتى وإن لم تنتقل أي أموال من يد إلى يد، لأنها أساءت استخدام السلطة التي ائتمنتها عليها هيئة عامة لتحقيق منفعة لأحد أفراد عائلتها. ويجمع قرارها بين المحسوبية، إذ فُضّل أحد الأقارب بصرف النظر عن الجدارة، وتضارب مصالح غير مُفصح عنه، إذ أثّر ولاؤها الخاص في أداء واجب مهني. ويقوم دفاعها على فهم خاطئ للتعريف؛ فالمكسب الخاص لا يُشترط أن يكون نقدًا، والمنافع التي تعود على أفراد العائلة أو على المكانة الاجتماعية تُحتسب أيضًا. والضرر حقيقي، لأن المال العام لم يُنفق على العرض الأفضل قيمةً لبناء مدرسة. وكان ينبغي لها أن تُفصح عن القرابة فورًا وتنسحب من اتخاذ القرار، لتتيح للجنة مستقلة اختيار المورّد على أساس الجدارة.", rubric:[["1–2","تنظيم محدود؛ استخدام قليل للمفردات الأساسية أو انعدامه؛ الحكم غير مشروح."],["3–4","تنظيم أساسي؛ استخدام مصطلح أو مصطلحين أساسيين؛ لم يُتناوَل الدفاع."],["5–6","بنية تحليلية واضحة؛ استخدام 3 مصطلحات أساسية بدقة؛ تناوُل الدفاع ببعض التعليل."],["7–8","حجّة متقنة ومحكمة البناء؛ استخدام 4 مصطلحات أساسية أو أكثر بدقة؛ دحض مقنع للدفاع؛ توصية محدّدة ومبرّرة."]], starters:["يُعدّ سلوك المديرة فسادًا / لا يُعدّ فسادًا لأن ___.","هذا مثال على ___، إذ إن ___.","إن دفاعها بأنها «لم تأخذ أي مال» دفاع ضعيف لأن ___.","كان ينبغي لها أن ___، وهذا كان سيؤدي إلى ___."]},
  task3:{title:"مهمة المشروع", mins:"حصتان", criterion:"المعيار D — التفكير الناقد", name:"خريطة مخاطر الفساد", steps:["في مجموعات من 3 إلى 4 طلاب، ستتسلّمون ملفًا تعريفيًا لمدينة متخيَّلة فيها وزارة ومستشفى وميناء واتحاد رياضي وشركة بناء كبيرة.","حدّدوا لكل مؤسسة نقاط اتخاذ القرار التي يمكن فيها إساءة استخدام السلطة المؤتمنة (مثل إصدار التراخيص، وترسية العقود، وتوظيف الموظفين).","رتّبوا المؤسسات من الأعلى إلى الأدنى في مخاطر الفساد، مع تبرير الترتيب بمعايير واضحة (مثل حجم الميزانيات، ومستوى السلطة التقديرية، ومقدار الرقابة).","اقترحوا ضمانة واقعية واحدة لنقطة القرار الأعلى خطورة.","اعرضوا خريطة المخاطر في إحاطة مدتها 4 دقائق، كأنكم تقدّمون المشورة لجهاز الرقابة والمحاسبة في المدينة. استخدموا مفردات بنك الكلمات طوال العرض."], rubric:[["1–2","نقاط الخطر غامضة أو مفقودة؛ الترتيب غير مبرّر."],["3–4","تحديد بعض نقاط الخطر؛ تبرير محدود للترتيب."],["5–6","نقاط خطر واضحة لكل مؤسسة؛ ترتيب مبرّر بمعايير منطقية؛ اقتراح ضمانة ذات صلة."],["7–8","تحليل مخاطر عميق ودقيق؛ تطبيق المعايير باتّساق؛ ضمانة واقعية ومحدّدة ومقيَّمة تقييمًا ناقدًا."]]},
  game:{type:"sort", title:"سمِّ شكل الفساد", prompt:"صنّف كل حالة تحت شكل الفساد الذي تمثّله على أفضل وجه.", bins:["الرشوة","الاختلاس","المحسوبية / تضارب المصالح"], items:[["سائق يعطي شرطي مرور نقودًا ليتجنّب مخالفة",0],["موظف مالي يحوّل أموال مشروع سرًّا إلى حسابه الشخصي",1],["مديرة توظّف ابن أخيها بدلًا من متقدّمين أكفأ منه",2],["شركة تدفع لمفتّش كي يتغاضى عن مخالفات السلامة",0],["أمين صندوق جمعية خيرية يستخدم التبرعات لتمويل عطلة عائلية",1],["عضو مجلس بلدي يصوّت لإقرار مشروع ستنفّذه شركته دون أن يُفصح عن ذلك",2],["موظف حكومي يستخدم سيارة حكومية وبطاقة وقود حكومية لنشاط تجاري خاص",1],["مورّد يعرض على مسؤول مشتريات «أتعاب استشارية» مقابل الفوز بمناقصة",0]]},
  quiz:[["ما تعريف الفساد الأكثر شيوعًا؟",["أي فعل غير قانوني ترتكبه حكومة","إساءة استخدام السلطة المؤتمنة لتحقيق مكاسب خاصة","أي خلاف حول طريقة إنفاق الأموال"],1],["ما الذي يجعل الهدية رشوة على الأرجح؟",["أنها مغلّفة","أن صديقًا قدّمها","أنها تهدف إلى التأثير بطريقة غير مشروعة في قرار شخص يملك السلطة"],2],["ما الاختلاس؟",["سرقة أموال أو ممتلكات اؤتمن الشخص على إدارتها، أو إساءة استخدامها","تفضيل أحد الأقارب في وظيفة","تهديد شخص للحصول على المال"],0],["قاضية تنظر في قضية تخصّ شركة أخيها لديها…",["لا مشكلة، ما دامت عادلة","تضارب مصالح ينبغي لها أن تُفصح عنه وتتنحّى عن القضية","واجب الحكم لمصلحة أخيها"],1],["لماذا تُعدّ المشتريات الحكومية مجالًا عالي الخطورة للفساد؟",["لأنها تتضمّن مبالغ كبيرة ونقاط قرار تقديرية كثيرة","لأن أحدًا لا يراجعها أبدًا","لأن صغار الموظفين وحدهم يتخذون القرارات"],0],["في النص، لماذا يُعدّ دفاع المديرة («لم آخذ أي مال») ضعيفًا؟",["لأنه كان ينبغي لها أن تطلب مالًا","لأن قواعد المشتريات لا تنطبق على الشركات العائلية","لأن المكسب الخاص قد يشمل منافع للعائلة، لا النقد فقط"],2],["هل يمكن أن يحدث الفساد في القطاع الخاص؟",["لا، الحكومات وحدها يمكن أن تكون فاسدة","نعم، مثل الرشوة بين الشركات أو إساءة الموظفين استخدام مناصبهم","في الشركات الصغيرة جدًا فقط"],1],["ما الاتفاقية الدولية لمكافحة الفساد التي صادقت عليها دولة الإمارات عام 2006؟",["اتفاق باريس","اتفاقيات جنيف","اتفاقية الأمم المتحدة لمكافحة الفساد"],2]],
  exit:"اشرح في جملة واحدة لماذا لا يتضمّن الفساد دائمًا انتقال أموال من يد إلى يد.",
  copy:{facts:["الفساد هو إساءة استخدام السلطة المؤتمنة لتحقيق مكاسب خاصة، وقد يشمل «المكسب» منافع للعائلة أو الأصدقاء أو المكانة، لا النقد فقط.","من أشكاله الرئيسة: الرشوة، والاختلاس، والمحسوبية، وتضارب المصالح، والابتزاز.","يحدث الفساد في القطاعين العام والخاص، ولا سيما حيث تجتمع الميزانيات الكبيرة مع السلطة التقديرية الواسعة والرقابة الضعيفة؛ وقد صادقت دولة الإمارات على اتفاقية الأمم المتحدة لمكافحة الفساد عام 2006."]},
  next:"الحصة القادمة: نواصل الوحدة الأولى بتحليل أسباب حدوث الفساد، أي الضغوط والفرص والأعذار التي تقف وراءه."
 },
 {
  id:"l2", lesson:2, title:"لماذا يحدث الفساد؟", unit:"الوحدة الأولى: الأخلاق في حياتنا المعاصرة", art:"reason",
  dna:"مراجعة: عرّف الفساد في جملة واحدة واذكر أحد أشكاله. والآن فكّر: معظم من يرتكبون الفساد لا يرون أنفسهم «أشخاصًا سيئين». اكتب عذرًا واحدًا قد يقوله شخص لنفسه ليبرّر قبوله رشوة.",
  dnaQs:["عرّف الفساد واذكر أحد أشكاله (من الحصة السابقة).","اكتب عذرًا واحدًا قد يقوله شخص لنفسه ليبرّر قبوله رشوة.","لماذا قد يُقنع أشخاص عاديون أنفسهم بأن الفساد مقبول؟"],
  dnaHint:"الفساد هو إساءة استخدام السلطة المؤتمنة لتحقيق مكاسب خاصة (مثل الرشوة والاختلاس والمحسوبية). ومن الأعذار الشائعة: «الجميع يفعل ذلك»، و«راتبي قليل، لذا أستحق ذلك»، و«إنه مبلغ صغير فقط»، و«لا أحد يتضرّر فعلًا»، و«سأعيده لاحقًا». وهذه أمثلة على التبرير، أي التفكير الذي يجعل السلوك الخاطئ يبدو مقبولًا.",
  intentions:["أن أفهم الأسباب الفردية والمؤسسية والثقافية للفساد.","أن أطبّق نماذج نظرية، مثل مثلث الاحتيال ومعادلة كليتغارد، لتفسير سبب حدوث الفساد.","أن أقيّم الأسباب الأكثر أهمية، وما يعنيه ذلك لمنع الفساد."],
  criteria:["أستطيع أن أشرح الأسباب الفردية والمؤسسية والثقافية للفساد.","أستطيع أن أطبّق مثلث الاحتيال ومعادلة كليتغارد على حالة ما.","أستطيع أن أقيّم الأهمية النسبية لمختلف الأسباب، وأربطها باستراتيجيات الوقاية."],
  concept:{key:"السببية", related:"الاختيار، الأنظمة", soi:"ينتج الفساد عن تفاعل الضغوط الشخصية والفرص المؤسسية والأعذار التي يستخدمها الناس لتبرير الخطأ.", context:"العدالة والتنمية: استكشاف كيفية تفاعل الخيارات الفردية والأنظمة المؤسسية لإنتاج نتائج غير أخلاقية.", uae:"تؤكّد الأخلاق الإسلامية قيمة الأمانة والمساءلة أمام الله؛ وتحدّ المؤسسات في دولة الإمارات من فرص الفساد من خلال التدقيق والخدمات الحكومية الرقمية؛ ويرتبط الموضوع بمادتَي علم النفس (فكّ الارتباط الأخلاقي) والاقتصاد (الحوافز) في برنامج الدبلوما."},
  words:[["مثلث الاحتيال (Fraud triangle)","نموذج (لكريسي) ينصّ على أن الاحتيال يتطلّب عادةً اجتماع الضغط والفرصة والتبرير معًا."],["الضغط (Pressure)","دافع شخصي، مثل الديون أو الجشع أو الخوف من الفشل، يدفع الشخص نحو ارتكاب الخطأ."],["الفرصة (Opportunity)","ظروف، مثل ضعف الرقابة، تسمح بحدوث الخطأ دون أن يُكتشف."],["التبرير (Rationalisation)","تفكير يجعل السلوك الخاطئ يبدو مقبولًا في نظر من يقوم به."],["السلطة التقديرية (Discretion)","حرية اتخاذ القرارات وفق الحكم الشخصي."],["التطبيع (Normalisation)","العملية التي يصبح فيها الخطأ أمرًا عاديًا أو متوقّعًا داخل جماعة ما."]],
  task1:{title:"مهمة البحث", mins:20, criterion:"المعيار B — البحث والاستقصاء", steps:["ابحث في أحد التفسيرات الآتية للفساد: مثلث الاحتيال (كريسي)، أو معادلة كليتغارد (الفساد = الاحتكار + السلطة التقديرية − المساءلة)، أو فكرة التطبيع داخل المؤسسات.","استعن بمصدرين موثوقين على الأقل (مثل الملخّصات الأكاديمية، أو مكتب الأمم المتحدة المعني بالمخدرات والجريمة، أو الهيئات المهنية للمحاسبة).","سجّل: ما الذي يقوله النموذج، والعوامل الرئيسة التي يحدّدها.","طبّق النموذج على حالة فساد واحدة واقعية أو قريبة من الواقع، واذكر أحد حدود النموذج."], prompts:["النموذج الذي اخترته ومصدراي","ما الذي يقوله النموذج وعوامله الرئيسة","كيف يفسّر النموذج الحالة التي اخترتها","أحد حدود النموذج"], success:"تشرح الإجابات القوية النموذج بدقة: فمثلث الاحتيال يركّز على الفرد (الضغط، الفرصة، التبرير)، في حين تركّز معادلة كليتغارد على المؤسسة (الاحتكار والسلطة التقديرية يزيدان الخطر، والمساءلة تقلّله). وللوصول إلى أعلى مستوى، طبّق النموذج بدقة على حالة ما، وحدّد أحد حدوده الحقيقية؛ فمثلًا قد يقلّل مثلث الاحتيال من دور الثقافة المؤسسية، أو قد تكون معادلة كليتغارد تبسيطًا لا يمكن قياسه رقميًا."},
  task2:{title:"مهمة القراءة والكتابة", mins:25, criterion:"المعيار C — التواصل", extract:"موظف تراخيص في بلدية متخيَّلة هو الشخص الوحيد الذي يوافق على الرخص التجارية. لا أحد يراجع قراراته، وقد تستغرق الطلبات شهورًا. وهو يعاني ديونًا عائلية. يبدأ المتقدّمون بعرض «مدفوعات تسريع» للحصول على رخصهم بسرعة أكبر، فيقول لنفسه: «أنا لا أرفض أحدًا، بل أساعد المستعجلين فقط».", steps:["في فقرة تحليلية منظّمة، استخدم مثلث الاحتيال لتفسير سبب تحوّل الموظف إلى الفساد، محدّدًا الضغط والفرصة والتبرير.","استخدم معادلة كليتغارد لتوضيح الخطأ الذي وقعت فيه المؤسسة.","استخدم أربع كلمات على الأقل من بنك الكلمات استخدامًا دقيقًا، واختم بتحديد العامل الذي سيكون تغييره الأكثر فاعلية."], model:"يمكن تفسير فساد الموظف باستخدام مثلث الاحتيال: فديونه العائلية تولّد الضغط، وكونه الموافق الوحيد دون أي مراجعة يمنحه الفرصة، واعتقاده أنه «يساعد المستعجلين فقط» تبرير واضح يُلبس الرشوة ثوب الخدمة. وتُظهر معادلة كليتغارد أن المؤسسة أخفقت هي الأخرى؛ إذ احتكر الموظف إصدار الرخص، وامتلك سلطة تقديرية كاملة على توقيتها، ولم يخضع لأي مساءلة لأن أحدًا لم يراجع قراراته. ومع أن الضغط الشخصي الذي يتعرّض له حقيقي، فإن العامل الأكثر فاعلية في التغيير هو الفرصة، لأن المؤسسة تستطيع التحكّم فيها مباشرة، كأن تعتمد نظامًا إلكترونيًا بمُدد زمنية ثابتة وتدقيقًا عشوائيًا، في حين لا يمكنها إزالة الصعوبات المالية لكل موظف.", rubric:[["1–2","تنظيم محدود؛ النموذجان غير مستخدمين أو مستخدمان بشكل خاطئ."],["3–4","تنظيم أساسي؛ تطبيق جزئي لنموذج واحد؛ استخدام مصطلح أو مصطلحين أساسيين."],["5–6","بنية واضحة؛ تطبيق النموذجين ببعض الدقة؛ استخدام 3 مصطلحات أساسية؛ اختيار عامل ما."],["7–8","تحليل متقن؛ تطبيق النموذجين بدقة؛ استخدام 4 مصطلحات أساسية أو أكثر بدقة؛ تبرير مقنع لاختيار العامل."]], starters:["باستخدام مثلث الاحتيال، يتمثّل الضغط في ___، والفرصة في ___، والتبرير في ___.","تُظهر معادلة كليتغارد أن المؤسسة ___.","مع أن ___، فإن العامل الأكثر فاعلية في التغيير هو ___ لأن ___.","فمثلًا، تستطيع البلدية أن ___."]},
  task3:{title:"مهمة المشروع", mins:"حصتان", criterion:"المعيار D — التفكير الناقد", name:"أعِد تصميم النظام", steps:["في مجموعات من 3 إلى 4 طلاب، اختاروا إجراءً متخيَّلًا واحدًا عالي الخطورة (مثل إصدار رخص القيادة، أو قوائم انتظار المواعيد في المستشفى، أو القبول الجامعي، أو التخليص الجمركي).","شخّصوا الإجراء باستخدام معادلة كليتغارد: أين الاحتكار؟ وأين السلطة التقديرية؟ وأين تغيب المساءلة؟","أعيدوا تصميم الإجراء للحدّ من مخاطر الفساد (مثل الخدمات الرقمية، وتدوير الموظفين، ونشر المعايير، والمراجعة المستقلة).","حدّدوا نتيجة واحدة غير مقصودة قد يُحدثها تصميمكم الجديد (مثل بطء الخدمة، أو استبعاد من لا يملكون إمكانية الوصول إلى الإنترنت)، وكيف ستتعاملون معها.","اعرضوا الإجراء قبل التعديل وبعده في عرض مدته 4 دقائق، مستخدمين مفردات بنك الكلمات."], rubric:[["1–2","التشخيص مفقود أو غير واضح؛ إعادة التصميم غامضة."],["3–4","تشخيص جزئي؛ إعادة التصميم تعالج بعض المخاطر؛ لم تُراعَ النتائج غير المقصودة."],["5–6","تشخيص واضح باستخدام النموذج؛ إعادة تصميم واقعية؛ تحديد نتيجة غير مقصودة ومعالجتها."],["7–8","تشخيص دقيق وعميق؛ إعادة تصميم واقعية ومحدّدة ومبرّرة جيدًا؛ تقييم مدروس للنتائج غير المقصودة."]]},
  game:{type:"sort", title:"تصنيف مثلث الاحتيال", prompt:"صنّف كل عامل تحت ضلع مثلث الاحتيال الذي يمثّله.", bins:["الضغط","الفرصة","التبرير"], items:[["ديون شخصية كبيرة",0],["لا أحد يراجع الحسابات",1],["«الجميع في هذا القسم يفعلون ذلك»",2],["الخوف من فقدان المكانة إذا لم تتحقّق الأهداف",0],["شخص واحد يتحكّم في المدفوعات والسجلات معًا",1],["«الشركة تدفع لي أقل مما أستحق، لذا أستحق هذا»",2],["عدم وجود قناة للإبلاغ عن المخالفات",1],["«إنه مبلغ صغير فقط، ولا أحد يتضرّر فعلًا»",2]]},
  quiz:[["ما العناصر الثلاثة لمثلث الاحتيال؟",["الضغط والفرصة والتبرير","المال والسلطة والشهرة","الجشع والحظ والتوقيت"],0],["وفقًا لمعادلة كليتغارد، يزداد الفساد مع…",["زيادة المساءلة","زيادة الاحتكار والسلطة التقديرية، وقلّة المساءلة","زيادة المنافسة والشفافية"],1],["عبارة «الجميع يفعل ذلك، لذا فهو ليس خطأً حقًّا» مثال على…",["الفرصة","الضغط","التبرير"],2],["ما المقصود بـ«تطبيع» الفساد؟",["جعل الفساد مخالفًا للقانون","أن يصبح الخطأ أمرًا عاديًا أو متوقّعًا داخل جماعة ما","الإبلاغ عن الفساد إلى السلطات"],1],["في النص، ما الذي منح الموظف فرصة الوقوع في الفساد؟",["ديونه العائلية","كونه الموافق الوحيد وعدم مراجعة أحد لقراراته","استعجال المتقدّمين"],1],["لماذا تركّز المؤسسات غالبًا على تقليل الفرصة؟",["لأنها العامل الذي تستطيع التحكّم فيه بشكل مباشر أكثر من غيره","لأن الضغط والتبرير لا أهمية لهما","لأنها الخيار الأرخص في كل الحالات"],0],["أيّ مما يأتي مثال على سبب مؤسسي للفساد؟",["جشع الشخص","ديون الشخص الخاصة","إجراءات معقّدة بلا رقابة"],2],["ترتبط قيمة الأمانة في الإسلام بالفساد لأنها تؤكّد…",["السرعة في إنجاز المهام","الأمانة في التعامل مع ما اؤتمنت عليه","المنافسة بين الموظفين"],1]],
  exit:"أيّهما السبب الأهم للفساد: الشخص أم النظام؟ أجب في جملة واحدة مع التبرير.",
  copy:{facts:["ينصّ مثلث الاحتيال على أن الفساد يحتاج عادةً إلى اجتماع الضغط والفرصة والتبرير معًا.","معادلة كليتغارد: الفساد = الاحتكار + السلطة التقديرية − المساءلة، وهي توضّح أهمية التصميم المؤسسي.","أسباب الفساد فردية (الجشع، الحاجة)، ومؤسسية (ضعف الرقابة، اتساع السلطة التقديرية)، وثقافية (التطبيع، «الجميع يفعل ذلك»)."]},
  next:"الحصة القادمة: نواصل الوحدة الأولى بتقييم عواقب الفساد على الأفراد والمجتمعات والدول."
 },
 {
  id:"l3", lesson:3, title:"عواقب الفساد", unit:"الوحدة الأولى: الأخلاق في حياتنا المعاصرة", art:"globe",
  dna:"مراجعة: اذكر في جملة واحدة أضلاع مثلث الاحتيال الثلاثة. والآن فكّر: دُفعت رشوة قيمتها بضع مئات من الدراهم كي يجتاز مبنى فحص السلامة. اكتب شخصين قد يتضرّران: أحدهما واضح، والآخر أقل وضوحًا.",
  dnaQs:["اذكر أضلاع مثلث الاحتيال الثلاثة (من الحصة السابقة).","اذكر شخصًا واحدًا متضرّرًا بشكل واضح من رشوة فحص السلامة.","اذكر شخصًا أو فئة متضرّرة بشكل أقل وضوحًا، واشرح كيف."],
  dnaHint:"أضلاع مثلث الاحتيال هي الضغط والفرصة والتبرير. ومن الضحايا الواضحين الأشخاص الذين سيسكنون المبنى غير الآمن أو يعملون فيه. أما الضحايا الأقل وضوحًا فمنهم المقاولون النزيهون الذين يخسرون أعمالهم لأنهم دفعوا تكاليف أعمال السلامة اللازمة، وشركات التأمين، وخدمات الطوارئ، وعموم الناس الذين تتضرّر ثقتهم بجميع عمليات الفحص.",
  intentions:["أن أفهم العواقب الاقتصادية والاجتماعية والسياسية والشخصية للفساد.","أن أحلّل كيف يمكن لأفعال فساد صغيرة أن تُحدث ضررًا كبيرًا وواسع الانتشار.","أن أقيّم الادعاء بأن الفساد «جريمة بلا ضحايا»."],
  criteria:["أستطيع أن أشرح العواقب الاقتصادية والاجتماعية والسياسية والشخصية للفساد.","أستطيع أن أتتبّع كيف يؤدي فعل فساد واحد إلى سلسلة من الأضرار الأوسع.","أستطيع أن أبني تقييمًا معلّلًا للادعاء بأن الفساد بلا ضحايا."],
  concept:{key:"التفاعلات العالمية", related:"العواقب، الإنصاف", soi:"يُلحق الفساد الضرر بالاقتصادات، ويُضعف الثقة بالمؤسسات، ويعمّق عدم المساواة؛ لذا تمتدّ أضراره إلى ما هو أبعد بكثير من الأشخاص المتورّطين فيه مباشرة.", context:"العدالة والتنمية: استكشاف كيفية تأثير القرارات غير الأخلاقية في التنمية والإنصاف والثقة الاجتماعية.", uae:"يُظهر مؤشر مدركات الفساد الصادر عن منظمة الشفافية الدولية كيف يؤثّر الفساد المُدرَك في سمعة الدولة وفي الاستثمار فيها؛ وتحقّق دولة الإمارات باستمرار أداءً قويًا على مستوى منطقة الخليج؛ ويرتبط الموضوع بمادتَي الاقتصاد (التنمية، الاستثمار) والسياسة العالمية (الشرعية) في برنامج الدبلوما."},
  words:[["الثقة العامة (Public trust)","ثقة المواطنين بأن المؤسسات ستتصرّف بعدل ونزاهة."],["عدم المساواة (Inequality)","فروق غير عادلة بين الفئات في الثروة أو الفرص أو إمكانية الحصول على الخدمات."],["سيادة القانون (Rule of law)","مبدأ خضوع الجميع، بمن فيهم القادة، على قدم المساواة لقوانين عادلة ومعلنة."],["الشرعية (Legitimacy)","القبول العام بأن لسلطة ما الحق في الحكم أو اتخاذ القرارات."],["تكلفة الفرصة البديلة (Opportunity cost)","ما يُفقَد عند استخدام الموارد بطريقة ما بدلًا من أفضل بديل متاح."],["الأثر المتتابع (Ripple effect)","الطريقة التي ينتشر بها فعل واحد إلى الخارج ليُحدث عواقب كثيرة أخرى."]],
  task1:{title:"مهمة البحث", mins:20, criterion:"المعيار B — البحث والاستقصاء", steps:["اختر مجالًا واحدًا وُثّقت فيه عواقب الفساد جيدًا: الرعاية الصحية، أو البنية التحتية والبناء، أو التعليم، أو البيئة، أو الرياضة، أو الاستثمار الأجنبي.","ابحث فيه مستعينًا بمصدرين موثوقين على الأقل (مثل منظمة الشفافية الدولية، أو البنك الدولي، أو مكتب الأمم المتحدة المعني بالمخدرات والجريمة، أو مؤسسات إخبارية موثوقة).","سجّل: كيف يُلحق الفساد في هذا المجال الضرر بالناس، وهل الضرر اقتصادي أم اجتماعي أم سياسي أم شخصي.","اشرح كيف يقيس مؤشر مدركات الفساد مستوى الفساد، وحدّد أحد حدود قياس الفساد بالاعتماد على الإدراك."], prompts:["المجال الذي اخترته ومصدراي","كيف يُلحق الفساد الضرر بالناس في هذا المجال","نوع الضرر أو أنواعه: اقتصادي، اجتماعي، سياسي، شخصي","كيف يعمل مؤشر مدركات الفساد، وأحد حدود قياس الإدراك"], success:"تقدّم الإجابات القوية آليات محدّدة، مثل تحويل ميزانيات الصحة الذي يؤدي إلى نقص الأدوية، أو الفحوص المدفوع لها رشاوى التي تؤدي إلى مبانٍ غير آمنة. ويرتّب مؤشر مدركات الفساد الدول وفق مستوى الفساد المُدرَك في القطاع العام، بالاعتماد على استطلاعات آراء الخبراء ورجال الأعمال. وللوصول إلى أعلى مستوى، استخدم مصدرين موثوقين، وقيّم أحد الحدود الحقيقية؛ فمثلًا قد يختلف الإدراك عن الواقع، ويركّز المؤشر على القطاع العام، وقد لا يرصد الفساد الذي ترتكبه شركات الدولة في الخارج."},
  task2:{title:"مهمة القراءة والكتابة", mins:25, criterion:"المعيار C — التواصل", extract:"يكتب كاتب عمود صحفي: «الفساد جريمة بلا ضحايا. فعندما يدفع رجل أعمال لموظف كي يسرّع إصدار رخصة، يكون الطرفان راضيين: رجل الأعمال يوفّر الوقت، والموظف يكسب قليلًا من المال الإضافي. ولا أحد يتضرّر».", steps:["اكتب فقرة تقييمية منظّمة (أو فقرتين) تردّ فيها على ادعاء كاتب العمود.","اعترف بأي جزء من الادعاء يبدو معقولًا، ثم فنّده باستخدام نوعين على الأقل من العواقب (اقتصادية، أو اجتماعية، أو سياسية، أو شخصية).","استخدم أربع كلمات على الأقل من بنك الكلمات استخدامًا دقيقًا، وتوصّل إلى استنتاج واضح ومبرّر."], model:"يُصيب كاتب العمود حين يقول إن الطرفين في هذا التبادل قد يشعران في تلك اللحظة بأنهما استفادا، وهذا تحديدًا ما يجعل هذا النوع من الفساد شديد الاستمرار. غير أن الادعاء بأن «لا أحد يتضرّر» يتجاهل الأثر المتتابع. فمن الناحية الاقتصادية، يُدفع كل متقدّم لا يستطيع الدفع أو يرفضه إلى آخر الطابور، فتواجه الشركات النزيهة تأخيرًا وتكاليف يتجنّبها منافسوها الفاسدون، وقد يتجنّب المستثمرون نظامًا يرونه غير عادل. ومن الناحيتين الاجتماعية والسياسية، تُعلّم كل دفعة المواطنين أن القواعد يمكن شراؤها، مما يُضعف الثقة العامة ويُوهن سيادة القانون، لأن القانون لم يعد يُطبَّق على الجميع بالتساوي. ومع مرور الوقت، يقوّض ذلك شرعية المؤسسة نفسها. لذا فالفساد ليس بلا ضحايا، بل إن ضحاياه أقل ظهورًا فحسب من الذين يستفيدون منه.", rubric:[["1–2","تنظيم محدود؛ قبول الادعاء أو رفضه دون تعليل."],["3–4","تنظيم أساسي؛ مناقشة نوع واحد من العواقب؛ استخدام مصطلح أو مصطلحين أساسيين."],["5–6","بنية تقييمية واضحة؛ مناقشة نوعين من العواقب؛ استخدام 3 مصطلحات أساسية؛ استنتاج واضح."],["7–8","تقييم متقن ومتوازن؛ معالجة جيدة للتسليم الجزئي والتفنيد؛ استخدام 4 مصطلحات أساسية أو أكثر بدقة؛ استنتاج مقنع ومبرّر."]], starters:["يُصيب كاتب العمود في أن ___؛ غير أن ___.","من الناحية الاقتصادية، يُلحق هذا التبادل الضرر بـ ___ لأن ___.","من الناحيتين الاجتماعية والسياسية، فإن كل دفعة ___.","لذا فالفساد ليس بلا ضحايا، لأن ___."]},
  task3:{title:"مهمة المشروع", mins:"حصتان", criterion:"المعيار D — التفكير الناقد", name:"تحقيق في الأثر المتتابع", steps:["في مجموعات من 3 إلى 4 طلاب، ستتسلّمون فعل فساد متخيَّلًا واحدًا (مثل مسؤول امتحانات مرتشٍ، أو تقرير بيئي مزوَّر، أو مناقصة مُتلاعَب بها لشراء معدات مستشفى).","أنشئوا مخططًا للأثر المتتابع يتتبّع العواقب من الداخل إلى الخارج: الفورية، وقصيرة المدى، وطويلة المدى، والوطنية أو الدولية.","صنّفوا كل عاقبة بوصفها اقتصادية أو اجتماعية أو سياسية أو شخصية.","حدّدوا النقطة في السلسلة التي كان يمكن عندها لتدخّل ما (تدقيق، أو مُبلِّغ عن المخالفات، أو صحفي) أن يوقف الضرر.","اعرضوا المخطط في إحاطة مدتها 4 دقائق، مستخدمين مفردات بنك الكلمات."], rubric:[["1–2","تحديد عواقب قليلة؛ ترابط ضعيف بينها."],["3–4","تحديد بعض العواقب؛ سلسلة منطقية جزئيًا؛ تصنيف محدود."],["5–6","سلسلة واضحة ومنطقية عبر مستويات عدة؛ تصنيف صحيح للعواقب؛ تحديد نقطة تدخّل منطقية."],["7–8","سلسلة عميقة ومعلّلة جيدًا تشمل عواقب أقل وضوحًا؛ تصنيف دقيق؛ تبرير مقنع لنقطة التدخّل."]]},
  game:{type:"sort", title:"نوع العاقبة", prompt:"صنّف كل عاقبة من عواقب الفساد وفق نوعها الرئيس.", bins:["اقتصادية","اجتماعية","سياسية"], items:[["شركات أجنبية تقرّر عدم الاستثمار في دولة ما",0],["المواطنون يتوقّفون عن الإيمان بأن العمل الجاد يقود إلى النجاح",1],["الناس يفقدون ثقتهم بنزاهة الانتخابات أو المحاكم",2],["هدر المال العام على مشاريع مبالغ في أسعارها",0],["اتساع الفجوة بين الأغنياء والفقراء",1],["سلطة ما تفقد شرعيتها في نظر المواطنين",2],["شركات نزيهة تخسر العقود لمصلحة من يدفعون الرشاوى",0],["أسر فقيرة لا تستطيع الحصول على الخدمات دون دفع مبالغ إضافية",1]]},
  quiz:[["ما المقصود بـ«الأثر المتتابع» للفساد؟",["انتشار فعل فساد واحد إلى الخارج ليُحدث أضرارًا كثيرة أخرى","اقتصار تأثير الفساد على المتورّطين فيه","اختفاء الفساد مع مرور الوقت"],0],["أيّ مما يأتي عاقبة اقتصادية للفساد؟",["فقدان الثقة بالمحاكم","تراجع الاستثمار الأجنبي وهدر الأموال العامة","زيادة احترام القانون"],1],["لماذا يزيد الفساد غالبًا من عدم المساواة؟",["لأن الجميع يدفعون الرشاوى نفسها","لأنه لا يحدث إلا في الدول الغنية","لأن القادرين على الدفع يحصلون على ما يُحرم منه الآخرون"],2],["ماذا يقيس مؤشر مدركات الفساد؟",["العدد الدقيق للرشاوى المدفوعة في دولة ما","المستويات المُدرَكة للفساد في القطاع العام، بالاعتماد على تقييمات الخبراء ورجال الأعمال","عدد المسجونين بسبب الفساد"],1],["ما أحد حدود قياس الفساد بالاعتماد على الإدراك؟",["قد يختلف الإدراك عن المستوى الفعلي للفساد","الإدراك دقيق تمامًا دائمًا","إنه يقيس الشركات الخاصة فقط"],0],["كيف يُضعف الفساد سيادة القانون؟",["بجعل القوانين أطول","بجعل المحاكم أسرع","بإظهار أن القواعد يمكن شراؤها، فلا يعود القانون يُطبَّق على الجميع بالتساوي"],2],["في النص، ما الذي يغفل عنه كاتب العمود؟",["أن رجل الأعمال وفّر الوقت","الضحايا الأقل ظهورًا، مثل المتقدّمين النزيهين والثقة العامة","أن الموظف كسب مالًا إضافيًا"],1],["لماذا قد يكون المقاول النزيه ضحية أقل وضوحًا لرشوة فحص السلامة؟",["لأنه يخسر أعماله لمصلحة منافسين يتهاونون في السلامة ويدفعون الرشاوى بدلًا منها","لأنه يتلقّى الرشوة","لأنه لا يعمل في المباني أبدًا"],0]],
  exit:"أكمل الجملة: «الفساد ليس جريمة بلا ضحايا لأن ___».",
  copy:{facts:["للفساد عواقب اقتصادية (الهدر، وخسارة الاستثمار)، واجتماعية (عدم المساواة، وفقدان الثقة)، وسياسية (إضعاف سيادة القانون والشرعية)، وشخصية (الملاحقة القضائية، وفقدان السمعة).","حتى أفعال الفساد الصغيرة تُحدث آثارًا متتابعة تُلحق الضرر بأشخاص لم يكونوا طرفًا في التبادل قط.","يقيس مؤشر مدركات الفساد الصادر عن منظمة الشفافية الدولية مستوى الفساد المُدرَك في القطاع العام، وهو ما يؤثّر في سمعة الدولة وجاذبيتها للاستثمار."]},
  next:"الحصة القادمة: نواصل الوحدة الأولى بدراسة السلوك غير الأخلاقي في التعليم: الانتحال، والغش، وإساءة استخدام الذكاء الاصطناعي."
 },
 {
  id:"l4", lesson:4, title:"السلوك غير الأخلاقي في التعليم", unit:"الوحدة الأولى: الأخلاق في حياتنا المعاصرة", art:"pen",
  dna:"مراجعة: اذكر في جملة واحدة عاقبة اقتصادية وأخرى اجتماعية للفساد. والآن فكّر: طالب ينسخ سؤال مقال في أداة ذكاء اصطناعي، ثم يعدّل الإجابة تعديلًا طفيفًا ويسلّمها على أنها عمله. اكتب: هل هذا مثل النقل من زميل؟ لماذا، أو لماذا لا؟",
  dnaQs:["اذكر عاقبة اقتصادية وأخرى اجتماعية للفساد (من الحصة السابقة).","هل تسليم عمل مُولَّد بالذكاء الاصطناعي بعد تعديله مثل النقل من زميل؟ لماذا، أو لماذا لا؟","من يتضرّر عندما يسلّم طالب عملًا ليس من إنتاجه؟"],
  dnaHint:"اقتصادية: هدر المال العام أو خسارة الاستثمار؛ اجتماعية: عدم المساواة أو فقدان الثقة. إن تسليم عمل مُولَّد بالذكاء الاصطناعي دون الإشارة إلى ذلك شكل من أشكال سوء السلوك الأكاديمي، لأن الطالب يقدّم أفكارًا وصياغات لم يُنتجها على أنها له، تمامًا كما في النقل من زميل. ومن المتضرّرين: الطالب نفسه (لأنه لا يتعلّم)، والزملاء النزيهون (لأن نتائجهم العادلة تفقد قيمتها)، والثقة التي تمنح المؤهلات قيمتها.",
  intentions:["أن أفهم الأشكال الرئيسة لسوء السلوك الأكاديمي، ومنها الانتحال والتواطؤ والغش التعاقدي وإساءة استخدام الذكاء الاصطناعي.","أن أحلّل العلاقة بين عدم الأمانة الأكاديمية والفساد في المجتمع الأوسع.","أن أقيّم الحدّ الفاصل بين الاستخدامات الأخلاقية وغير الأخلاقية للذكاء الاصطناعي في التعلّم."],
  criteria:["أستطيع أن أعرّف أشكال سوء السلوك الأكاديمي وأميّز بينها.","أستطيع أن أشرح كيف ترتبط عدم الأمانة الأكاديمية بالفساد وعواقبه.","أستطيع أن أصدر أحكامًا مبرّرة حول الاستخدامات الأخلاقية وغير الأخلاقية للذكاء الاصطناعي في العمل الأكاديمي."],
  concept:{key:"الهوية", related:"النزاهة، المسؤولية", soi:"تحمي النزاهة الأكاديمية قيمة التعلّم والمؤهلات، والعادات التي يكتسبها الطلاب في التعليم تشكّل النزاهة التي يحملونها معهم إلى حياتهم البالغة.", context:"الابتكار العلمي والتقني: استكشاف كيف تتحدّى التقنيات الجديدة، مثل الذكاء الاصطناعي التوليدي، المفاهيم التقليدية للعمل الأصيل والنزيه.", uae:"تخضع المؤهلات في دولة الإمارات لإجراءات رسمية للتحقّق والتصديق لأغراض التوظيف ومواصلة الدراسة، لذا تعتمد قيمتها على نزاهة التقييم؛ ويرتبط الموضوع بتوقّعات منظمة البكالوريا الدولية بشأن النزاهة الأكاديمية، وبمادة نظرية المعرفة (المعرفة والتكنولوجيا)، وبالمقال الموسّع."},
  words:[["النزاهة الأكاديمية (Academic integrity)","التصرّف بأمانة وعدل ومسؤولية في كل جوانب التعلّم والتقييم."],["الانتحال (Plagiarism)","تقديم كلمات شخص آخر أو أفكاره أو عمله على أنها للشخص نفسه دون الإشارة إلى المصدر."],["التواطؤ (Collusion)","العمل مع آخرين لإنتاج عمل يُسلَّم بعد ذلك على أنه عمل فردي خاص."],["الغش التعاقدي (Contract cheating)","الدفع لشخص آخر أو لجهة أخرى، أو الطلب منهما، إنجاز عمل خاضع للتقييم نيابةً عنك."],["الاختلاق (Fabrication)","اختراع البيانات أو النتائج أو المصادر أو تزويرها."],["الإشارة إلى المصادر (Acknowledgement)","الإشارة بوضوح إلى المصادر أو الأشخاص أو الأدوات (ومنها الذكاء الاصطناعي) المستخدمة في إنتاج العمل."]],
  task1:{title:"مهمة البحث", mins:20, criterion:"المعيار B — البحث والاستقصاء", steps:["ابحث في توقّعات منظمة البكالوريا الدولية بشأن النزاهة الأكاديمية، وكيفية تطبيقها على استخدام أدوات الذكاء الاصطناعي في الأعمال المقرّرة (مثل التقييمات الداخلية، والمقال الموسّع، ومقالات نظرية المعرفة).","استعن بمصدرين موثوقين على الأقل (مثل الإرشادات المنشورة لمنظمة البكالوريا الدولية، أو سياسة النزاهة الأكاديمية في إحدى الجامعات، أو أخبار تعليمية موثوقة).","سجّل: ما استخدامات الذكاء الاصطناعي التي تُعدّ مقبولة عمومًا، وما الاستخدامات التي تُعدّ سوء سلوك.","ابحث في شكل واحد من أشكال الفساد في التعليم خارج الصف (مثل بيع أوراق الامتحانات، أو الشهادات المزوّرة، أو الرشوة للقبول)، واذكر عواقبه."], prompts:["مصدراي","استخدامات الذكاء الاصطناعي المقبولة عمومًا","استخدامات الذكاء الاصطناعي التي تُعدّ سوء سلوك أكاديمي","شكل واحد من أشكال الفساد في التعليم، وعواقبه"], success:"تدرك الإجابات القوية أن الذكاء الاصطناعي ليس محظورًا حظرًا تامًا: فاستخدامه لتوليد الأفكار أو للتحقّق من الفهم أو لتحسين مهارات الدراسة قد يكون مقبولًا، في حين يُعدّ تقديم نصوص أو أفكار أو تحليلات مُولَّدة بالذكاء الاصطناعي على أنها عمل الطالب نفسه دون الإشارة إلى ذلك سوءَ سلوك. ويجب الإشارة بوضوح إلى أي مادة مُولَّدة بالذكاء الاصطناعي تُستخدم، وأن يبقى العمل عمل الطالب نفسه. وللوصول إلى أعلى مستوى، استخدم مصدرين موثوقين، واشرح بوضوح لماذا تُلحق الشهادات المزوّرة أو أوراق الامتحانات المشتراة الضرر بأصحاب العمل والمرضى والعملاء والخريجين النزيهين، لا بالغشّاش وحده."},
  task2:{title:"مهمة القراءة والكتابة", mins:25, criterion:"المعيار C — التواصل", extract:"طالبة في برنامج الدبلوما متأخرة في إنجاز تقييمها الداخلي. فتستخدم أداة ذكاء اصطناعي لتوليد قسم التحليل، ثم تعيد صياغته بعناية حتى «يبدو بأسلوبها». ولا تذكر الذكاء الاصطناعي في عملها. وتقول مدافعةً عن نفسها: «الأفكار مجرد معلومات عامة، وقد أعدت كتابة كل جملة بنفسي».", steps:["اكتب فقرة تقييمية منظّمة توضّح فيها ما إذا كانت الطالبة قد ارتكبت سوء سلوك أكاديمي.","رُدّ مباشرةً على جزأي دفاعها («معلومات عامة» و«أعدت كتابة كل جملة»).","استخدم أربع كلمات على الأقل من بنك الكلمات استخدامًا دقيقًا، واختم بما كان ينبغي لها أن تفعله بدلًا من ذلك."], model:"ارتكبت الطالبة سوء سلوك أكاديمي، لأنها قدّمت تحليلًا لم تُنتجه على أنه عملها دون أي إشارة إلى مصدره. ويسقط دفاعها الأول لأن قسم التحليل ليس معلومات عامة، بل هو الجزء من التقييم الداخلي الذي يُقيَّم فيه تفكير الطالب نفسه. ويسقط دفاعها الثاني كذلك، لأن إعادة الصياغة لا تُلغي ضرورة الإشارة إلى المصدر؛ فإعادة صياغة أفكار الآخرين دون نسبتها إليهم تظل انتحالًا، سواء أكان المصدر شخصًا أم أداة ذكاء اصطناعي. وتتجاوز أهمية ذلك درجةً واحدة: فهو يقوّض النزاهة الأكاديمية، ويظلم الزملاء النزيهين، ويُفقد المؤهل الذي تثق به الجامعات وأصحاب العمل قيمته. وكان ينبغي لها أن تتحدّث إلى معلّمتها بشأن الموعد النهائي، وإن استخدمت الذكاء الاصطناعي أصلًا، أن تشير إلى ذلك بوضوح وتُعدّ التحليل بنفسها.", rubric:[["1–2","تنظيم محدود؛ الحكم غير مشروح؛ استخدام قليل للمفردات الأساسية."],["3–4","تنظيم أساسي؛ تناوُل جزء واحد من الدفاع؛ استخدام مصطلح أو مصطلحين أساسيين."],["5–6","بنية تقييمية واضحة؛ تناوُل جزأي الدفاع؛ استخدام 3 مصطلحات أساسية؛ توصية منطقية."],["7–8","تقييم متقن ودقيق؛ دحض مقنع لجزأي الدفاع؛ استخدام 4 مصطلحات أساسية أو أكثر بدقة؛ مراعاة العواقب الأوسع."]], starters:["ارتكبت الطالبة / لم ترتكب سوء سلوك أكاديمي لأن ___.","إن ادعاءها بأن الأفكار «معلومات عامة» ادعاء ضعيف لأن ___.","لا تُلغي إعادة الصياغة ضرورة الإشارة إلى المصدر لأن ___.","بدلًا من ذلك، كان ينبغي لها أن ___."]},
  task3:{title:"مهمة المشروع", mins:"حصتان", criterion:"المعيار D — التفكير الناقد", name:"ميثاق الذكاء الاصطناعي لمرحلتنا الدراسية", steps:["في مجموعات من 3 إلى 4 طلاب، صوغوا ميثاقًا واضحًا لاستخدام الذكاء الاصطناعي لطلاب الصف الثالث عشر، يشمل الأعمال المقرّرة والواجبات المنزلية والمراجعة.","قسّموا استخدامات الذكاء الاصطناعي إلى ثلاث فئات: مقبول بوضوح، ومقبول فقط مع الإشارة إليه، وغير مقبول، مع ثلاثة أمثلة على الأقل في كل فئة.","برّروا كل فئة باستخدام مبادئ من حصة اليوم (الأمانة، والعدل، والتعلّم، والإشارة إلى المصادر).","حدّدوا منطقة رمادية واحدة اختلفت فيها مجموعتكم، واشرحوا كيف حسمتموها.","اعرضوا ميثاقكم في عرض مدته 4 دقائق، وسيصوّت الصف على أوضح ميثاق وأعدله. استخدموا مفردات بنك الكلمات طوال العرض."], rubric:[["1–2","فئات غير واضحة؛ أمثلة غامضة؛ تبرير قليل."],["3–4","فئات أساسية مع بعض الأمثلة؛ تبرير محدود."],["5–6","فئات واضحة مع أمثلة واقعية؛ تبرير قائم على مبادئ الحصة؛ تحديد منطقة رمادية."],["7–8","ميثاق دقيق وعملي؛ تبرير متّسق قائم على المبادئ؛ مناقشة المنطقة الرمادية بدقة حقيقية."]]},
  game:{type:"sort", title:"نزاهة أم سوء سلوك؟", prompt:"صنّف كل تصرّف: هل يُظهر النزاهة الأكاديمية، أم أنه سوء سلوك أكاديمي؟", bins:["النزاهة الأكاديمية","سوء السلوك الأكاديمي"], items:[["استخدام الذكاء الاصطناعي لتوليد أسئلة تدريبية للمراجعة",0],["تسليم فقرة كتبها الذكاء الاصطناعي على أنها تحليلك الخاص",1],["توثيق جميع المصادر، ومنها أداة الذكاء الاصطناعي التي استخدمتها، في قائمة المراجع",0],["الدفع لخدمة إلكترونية لكتابة مقالك الموسّع",1],["مناقشة الأفكار مع زميل، ثم كتابة عملك بشكل مستقل",0],["اختراع بيانات لتقرير مخبري لأن التجربة فشلت",1],["مشاركة تقييمك الداخلي المكتمل مع صديق كي «يتحقّق من بنيته»",1],["طلب تمديد الموعد من معلّمك عندما تواجه صعوبة حقيقية",0]]},
  quiz:[["ما الانتحال؟",["تقديم كلمات شخص آخر أو أفكاره أو عمله على أنها لك دون الإشارة إلى المصدر","الدراسة مع صديق","طلب المساعدة من المعلّم"],0],["الدفع لشخص آخر لإنجاز عملك المقرّر يُسمّى…",["التواطؤ","الغش التعاقدي","الإشارة إلى المصادر"],1],["هل إعادة صياغة نص مُولَّد بالذكاء الاصطناعي دون الإشارة إليه أمر مقبول؟",["نعم، ما دامت كل جملة قد أُعيدت صياغتها","نعم، إذا كانت أداة الذكاء الاصطناعي مجانية","لا، فإعادة صياغة أفكار الآخرين دون نسبتها إليهم تظل انتحالًا"],2],["ما التواطؤ؟",["العمل مع آخرين لإنتاج عمل يُسلَّم بعد ذلك على أنه عملك الفردي","اختراع البيانات","توثيق مصادرك"],0],["أيّ استخدامات الذكاء الاصطناعي هو الأرجح أن يكون مقبولًا؟",["توليد تحليل تقييمك الداخلي","توليد أسئلة مراجعة لاختبار فهمك","كتابة مقال نظرية المعرفة نيابةً عنك"],1],["كيف ترتبط عدم الأمانة الأكاديمية بالفساد الأوسع؟",["لا علاقة بينهما على الإطلاق","لا تهمّ إلا داخل مدرسة واحدة","تُفقد المؤهلات قيمتها وتبني عادات من عدم الأمانة قد يحملها الناس إلى العمل"],2],["لماذا تُلحق الشهادات المزوّرة الضرر بالمجتمع؟",["لأنها تضع أشخاصًا غير مؤهلين في أدوار يعتمد فيها الآخرون على مهاراتهم","لأنها توفّر على الناس الوقت","لأنها لا تضرّ إلا من اشتراها"],0],["ماذا ينبغي للطالب أن يفعل إذا تأخر عن موعد التسليم؟",["استخدام الذكاء الاصطناعي لإنجاز العمل سرًّا","نقل مسودة صديق","التحدّث إلى معلّمه بصدق وطلب الدعم"],2]],
  exit:"اكتب استخدامًا واحدًا للذكاء الاصطناعي تراه مقبولًا في دراستك، واستخدامًا واحدًا تراه غير مقبول، مع ذكر سبب لكل منهما.",
  copy:{facts:["يشمل سوء السلوك الأكاديمي الانتحال، والتواطؤ، والغش التعاقدي، والاختلاق، وتقديم عمل مُولَّد بالذكاء الاصطناعي على أنه عملك.","يجب الإشارة بوضوح إلى أي مادة مُولَّدة بالذكاء الاصطناعي تُستخدم في العمل، وأن يكون التفكير الخاضع للتقييم تفكير الطالب نفسه.","تُفقد عدم الأمانة الأكاديمية المؤهلات التي تعتمد عليها الجامعات وأصحاب العمل قيمتها، وتبني عادات قد تقود إلى الفساد لاحقًا في الحياة."]},
  next:"الحصة القادمة: نواصل الوحدة الأولى باستكشاف السلوك غير الأخلاقي في بيئة العمل، وكيف يتعامل المهنيون معه."
 },
 {
  id:"l5", lesson:5, title:"السلوك غير الأخلاقي في بيئة العمل", unit:"الوحدة الأولى: الأخلاق في حياتنا المعاصرة", art:"business",
  dna:"مراجعة: عرّف في جملة واحدة الانتحال والغش التعاقدي. والآن فكّر: إنه أسبوعك الأول في وظيفة جديدة، ويرسل إليك أحد المورّدين قسيمة هدايا باهظة الثمن «ترحيبًا بك في الفريق». اكتب ما ستفعله، وما الذي تودّ معرفته قبل أن تقرّر.",
  dnaQs:["عرّف الانتحال والغش التعاقدي (من الحصة السابقة).","ماذا ستفعل بقسيمة الهدايا التي أرسلها المورّد؟","ما الذي تودّ معرفته قبل أن تقرّر؟"],
  dnaHint:"الانتحال هو تقديم عمل شخص آخر على أنه عملك دون الإشارة إلى المصدر؛ والغش التعاقدي هو الدفع لشخص ما لإنجاز عملك. أما بشأن القسيمة، فتراعي الإجابة القوية: سياسة الشركة بشأن الهدايا، وقيمة الهدية، وما إذا كنت تتخذ قرارات تخصّ هذا المورّد، وما إذا كان قبولها قد يُنشئ التزامًا تجاهه. والاستجابة المهنية الأسلم عادةً هي الإفصاح عنها لمديرك واتّباع السياسة المعتمدة.",
  intentions:["أن أفهم الأشكال الشائعة للسلوك غير الأخلاقي في بيئة العمل، مثل الرشوة والعمولات السرّية والاحتيال وتضارب المصالح وإساءة استخدام الموارد.","أن أحلّل دور مدوّنات السلوك وسياسات الهدايا والإبلاغ عن المخالفات في الحفاظ على أخلاقيات العمل.","أن أقيّم كيف ينبغي للمهنيين التعامل مع المناطق الرمادية الأخلاقية والضغوط من الزملاء أو المديرين."],
  criteria:["أستطيع أن أحدّد أشكال السلوك غير الأخلاقي في بيئة العمل وأشرحها.","أستطيع أن أشرح كيف تحمي مدوّنات السلوك والإبلاغ عن المخالفات المؤسساتِ والجمهور.","أستطيع أن أقيّم أفضل استجابة لمعضلة أخلاقية في بيئة العمل، وأبرّر قراري."],
  concept:{key:"المسؤولية", related:"النزاهة، المساءلة", soi:"تعتمد أخلاقيات العمل على النزاهة الفردية وعلى أنظمة مؤسسية تجعل فعل الصواب أمرًا آمنًا.", context:"العولمة والاستدامة: استكشاف كيف تتصرّف الشركات والمؤسسات بمسؤولية في اقتصاد عالمي مترابط.", uae:"يَعُدّ القانون الجزائي الاتحادي في دولة الإمارات عرض الرشوة وقبولها، وكذلك التوسّط فيها، جرائم يعاقب عليها القانون؛ وتعتمد المؤسسات في الدولة عادةً مدوّنات السلوك وإقرارات تضارب المصالح؛ ويرتبط الموضوع بمادة إدارة الأعمال (الأخلاقيات، والمسؤولية الاجتماعية للشركات) في برنامج الدبلوما، وبأخلاقيات العمل التي يقدّرها التراث الإسلامي (الإتقان: الإحسان والإخلاص في العمل)."},
  words:[["مدوّنة السلوك (Code of conduct)","مجموعة مكتوبة من القواعد والقيم تصف السلوك المتوقّع داخل مؤسسة ما."],["العمولة السرّية (Kickback)","مبلغ يُدفع سرًّا لشخص ما مقابل ترتيبه عقدًا أو صفقة."],["المُبلِّغ عن المخالفات (Whistleblower)","شخص يُبلغ عن المخالفات داخل مؤسسة ما إلى الجهات القادرة على اتخاذ إجراء بشأنها."],["سياسة الهدايا والضيافة (Gifts and hospitality policy)","قواعد تحدّد الهدايا أو الوجبات أو الخدمات التي يجوز للموظفين قبولها، ومتى يجب الإفصاح عنها."],["سوء التصرّف في الأموال (Misappropriation)","استخدام أموال المؤسسة أو وقتها أو مواردها لأغراض شخصية غير مصرّح بها."],["العناية الواجبة (Due diligence)","تحرّيات دقيقة تُجرى قبل اتخاذ قرار ما، مثل التحقّق من نزاهة أحد المورّدين."]],
  task1:{title:"مهمة البحث", mins:20, criterion:"المعيار B — البحث والاستقصاء", steps:["ابحث عن مدوّنة سلوك أو سياسة أخلاقيات حقيقية ومتاحة للعامة لشركة كبيرة أو مؤسسة عامة.","استعن بالمدوّنة نفسها وبمصدر موثوق آخر على الأقل (مثل مقال إخباري أو دليل لأخلاقيات الأعمال).","سجّل: ما الذي تقوله المدوّنة عن الهدايا، وتضارب المصالح، والرشوة، والإبلاغ عن المخاوف.","قيّم نقطة قوة واحدة ونقطة ضعف واحدة في المدوّنة: هل سترشد فعلًا موظفًا يواجه قرارًا صعبًا؟"], prompts:["المؤسسة والمدوّنة اللتان اخترتهما، ومصدري الثاني","ما الذي تقوله عن الهدايا وتضارب المصالح","ما الذي تقوله عن الرشوة والإبلاغ عن المخاوف","نقطة قوة واحدة ونقطة ضعف واحدة في المدوّنة"], success:"تقتبس الإجابات القوية قواعد محدّدة أو تعيد صياغتها بدقة (مثل حدّ أقصى لقيمة الهدايا، أو اشتراط الإفصاح عن المصالح، أو خط سرّي للإبلاغ) بدلًا من التلخيص الغامض. وللوصول إلى أعلى مستوى، قيّم تقييمًا ناقدًا: فالمدوّنة لا تكون فعّالة إلا إذا تدرّب عليها الموظفون، وجسّدها القادة في سلوكهم، وحُمي من يُبدون مخاوفهم من الانتقام. أما المدوّنة الطويلة أو الغامضة أو التي لا تُطبَّق أبدًا، فقد تبقى «حبرًا على ورق»."},
  task2:{title:"مهمة القراءة والكتابة", mins:25, criterion:"المعيار C — التواصل", extract:"تلاحظ محاسبة مبتدئة في شركة متخيَّلة أن مديرها يوافق على دفعات لمورّد مقابل خدمات لم تُقدَّم قط. وعندما تُثير الأمر، يقول المدير: «هكذا تسير الأعمال هنا. التزمي الصمت وستحصلين على ترقية في العام القادم. أمّا إذا أثرتِ المشكلات، فلن تبقي طويلًا».", steps:["اكتب استجابة تقييمية منظّمة توضّح فيها أشكال السلوك غير الأخلاقي التي تحدث.","قيّم استجابتين محتملتين على الأقل يمكن أن تتّخذهما المحاسبة (مثل التزام الصمت، أو مواجهة المدير مرة أخرى، أو الإبلاغ عبر قناة داخلية، أو الإبلاغ إلى جهة خارجية).","استخدم أربع كلمات على الأقل من بنك الكلمات استخدامًا دقيقًا، واختم بالاستجابة التي تراها الأكثر تبريرًا، مع مراعاة الجانب الأخلاقي وحمايتها الشخصية معًا."], model:"يبدو أن المدير متورّط في احتيال، وربما في ترتيب لعمولات سرّية، لأن دفعات تُصرف مقابل خدمات لم تُقدَّم قط، وهذا سوء تصرّف في أموال الشركة. كما أن تعليقه محاولة للضغط على المحاسبة بمزيج من الترغيب والترهيب، وادعاؤه أن «هكذا تسير الأعمال» تبرير نموذجي. وقد يحمي التزام الصمت مسيرتها المهنية على المدى القصير، لكنه سيجعلها شريكة في المخالفة ومعرّضة للمساءلة إذا اكتُشف الاحتيال لاحقًا. ومن غير المرجّح أن تنجح مواجهة المدير مرة أخرى، لأنه أظهر بالفعل أنه لن يتصرّف. والاستجابة الأكثر تبريرًا هي الاحتفاظ بسجلات دقيقة وموضوعية، والإبلاغ عن المشكلة عبر قناة الإبلاغ السرّية عن المخالفات في الشركة، أو إلى إدارة التدقيق أو الامتثال فيها، وفقًا لما تنصّ عليه مدوّنة السلوك. وإذا أخفقت القنوات الداخلية، فقد تحتاج إلى طلب المشورة من جهة خارجية. فهذه الاستجابة تفي بواجبها الأخلاقي وتمنحها أكبر قدر من الحماية.", rubric:[["1–2","تنظيم محدود؛ عدم تحديد السلوك غير الأخلاقي بوضوح؛ استجابة واحدة فقط."],["3–4","تنظيم أساسي؛ تحديد جزئي للسلوك؛ ذكر موجز لاستجابتين؛ استخدام مصطلح أو مصطلحين أساسيين."],["5–6","بنية واضحة؛ تحديد دقيق للسلوك؛ تقييم استجابتين؛ استخدام 3 مصطلحات أساسية؛ استنتاج مبرّر."],["7–8","تقييم متقن؛ تحديد دقيق للسلوك؛ موازنة مدروسة بين استجابات عدة؛ استخدام 4 مصطلحات أساسية أو أكثر بدقة؛ استنتاج يوازن بإقناع بين الأخلاق والحماية الذاتية."]], starters:["ينطوي سلوك المدير على ___ لأن ___.","إن تعليقه بأن «هكذا تسير الأعمال» مثال على ___.","لو التزمت الصمت، لـ ___؛ غير أن ___.","الاستجابة الأكثر تبريرًا هي ___ لأن ___."]},
  task3:{title:"مهمة المشروع", mins:"حصتان", criterion:"المعيار D — التفكير الناقد", name:"ورشة تدريبية في الأخلاقيات", steps:["في مجموعات من 3 إلى 4 طلاب، تخيّلوا أنكم فريق الأخلاقيات والامتثال في شركة متخيَّلة توشك على التوسّع في سوق جديدة.","اكتبوا ثلاثة مواقف قصيرة وواقعية من بيئة العمل (مثل هدية من مورّد، أو طلب «تسريع» دفعة جمركية، أو مدير يوظّف أحد أقاربه).","اكتبوا لكل موقف «الاستجابة الصحيحة» وفق مدوّنة سلوك قوية، واشرحوا السبب.","صمّموا أداة بسيطة واحدة للموظفين (مثل مخطط انسيابي بعنوان «هل أقبل هذه الهدية؟» أو اختبار أخلاقي من خمسة أسئلة).","قدّموا ورشتكم للصف في 5 دقائق، مع إشراك الحضور في موقف واحد على الأقل. استخدموا مفردات بنك الكلمات طوال الورشة."], rubric:[["1–2","مواقف غير واقعية أو غير واضحة؛ استجابات غير مبرّرة."],["3–4","مواقف أساسية؛ استجابات مبرّرة جزئيًا؛ أداة غير واضحة."],["5–6","مواقف واقعية؛ استجابات مبرّرة بالرجوع إلى الأخلاقيات والسياسات؛ أداة واضحة ومفيدة."],["7–8","مواقف واقعية للغاية ودقيقة تشمل مناطق رمادية؛ استجابات مبرّرة بإقناع؛ أداة عملية وواضحة ومفيدة فعلًا."]]},
  game:{type:"sort", title:"مقبول، أم غير أخلاقي، أم منطقة رمادية؟", prompt:"صنّف كل موقف من مواقف العمل: هل هو مقبول، أم غير أخلاقي بوضوح، أم منطقة رمادية ينبغي الإفصاح عنها أو السؤال عنها أولًا؟", bins:["مقبول","غير أخلاقي بوضوح","منطقة رمادية: أفصِح أو اسأل أولًا"], items:[["قبول قلم يحمل شعار شركة في أحد المؤتمرات",0],["تلقّي مبلغ سرّي مقابل التوصية بمورّد",1],["تلقّي دعوة إلى عشاء فاخر من مورّد أثناء مناقصة",2],["الإبلاغ عن مخاوف عبر الخط الساخن السرّي للشركة",0],["المطالبة بنفقات رحلة لم تقم بها",1],["ابن عمك يتقدّم لوظيفة في فريق تديره",2],["استخدام وقت الشركة ومعدّاتها لإدارة مشروعك التجاري الخاص",1],["إجراء تحرّيات العناية الواجبة عن مورّد قبل توقيع عقد معه",0]]},
  quiz:[["ما العمولة السرّية؟",["مبلغ يُدفع سرًّا مقابل ترتيب عقد أو صفقة","مكافأة من الشركة على العمل الجيد","نوع من العقود"],0],["ما الهدف الرئيس من مدوّنة السلوك؟",["جعل الموظفين يعملون ساعات أطول","وصف السلوك المتوقّع ومساعدة الموظفين على اتخاذ قرارات أخلاقية","أن تحلّ محلّ القانون"],1],["من المُبلِّغ عن المخالفات؟",["مدير يضع الأهداف","مورّد يقدّم الخصومات","شخص يُبلغ عن المخالفات إلى الجهات القادرة على اتخاذ إجراء بشأنها"],2],["استخدام أموال الشركة لأغراض شخصية غير مصرّح بها يُسمّى…",["العناية الواجبة","سوء التصرّف في الأموال","الإشارة إلى المصادر"],1],["ما أفضل خطوة أولى إذا عرض عليك مورّد هدية قيّمة؟",["قبولها بهدوء","مراجعة سياسة الهدايا والإفصاح عنها لمديرك","إعطاؤها لزميل"],1],["في النص، لماذا يُعدّ التزام الصمت خيارًا محفوفًا بالمخاطر بالنسبة إلى المحاسبة؟",["لأنه يجعلها شريكة في المخالفة ومعرّضة للمساءلة إذا اكتُشف الاحتيال لاحقًا","لأنه يضمن ترقيتها","لأن القانون يفرضه"],0],["لماذا يجب على المؤسسات حماية المُبلِّغين عن المخالفات من الانتقام؟",["لأن المُبلِّغين على حق دائمًا","كي يشعر الناس بالأمان للإبلاغ عن المخالفات مبكرًا","لأن الإبلاغ لا يكون سرّيًا أبدًا"],1],["وفقًا للقانون الجزائي الاتحادي في دولة الإمارات، من يمكن أن يرتكب جريمة الرشوة؟",["من يقبل الرشوة فقط","من يعرض الرشوة فقط","من يعرضها ومن يقبلها، وكذلك الوسطاء"],2]],
  exit:"اكتب سؤالًا واحدًا ستطرحه على نفسك قبل قبول أي هدية في العمل.",
  copy:{facts:["يشمل السلوك غير الأخلاقي في بيئة العمل الرشوة، والعمولات السرّية، والاحتيال، وتضارب المصالح غير المُفصح عنه، وسوء التصرّف في الموارد.","تساعد مدوّنات السلوك، وسياسات الهدايا، والعناية الواجبة، وقنوات الإبلاغ المحمية عن المخالفات الموظفين على فعل الصواب.","يَعُدّ القانون الجزائي الاتحادي في دولة الإمارات عرض الرشوة وقبولها جريمتين؛ وتدعو قيمة الإتقان في الإسلام إلى الإخلاص والإحسان في العمل."]},
  next:"الحصة القادمة: نختتم الوحدة الأولى باستكشاف كيفية تعزيز السلوك الأخلاقي ومكافحة الفساد، في أنفسنا وفي الآخرين."
 },
 {
  id:"l6", lesson:6, title:"تعزيز السلوك الأخلاقي ومكافحة الفساد", unit:"الوحدة الأولى: الأخلاق في حياتنا المعاصرة", art:"toolkit",
  dna:"اختبار مفردات الوحدة الأولى! عرّف كل مصطلح بأكبر قدر ممكن من الدقة: الفساد، التبرير، سيادة القانون، النزاهة الأكاديمية، المُبلِّغ عن المخالفات. هذه هي الحصة الأخيرة في الوحدة الأولى، فلنرَ كم بقي في أذهاننا.",
  dnaQs:["الفساد والتبرير: ماذا يعني كل منهما؟","سيادة القانون والنزاهة الأكاديمية: ماذا يعني كل منهما؟","المُبلِّغ عن المخالفات: ماذا يعني؟"],
  dnaHint:"الفساد: إساءة استخدام السلطة المؤتمنة لتحقيق مكاسب خاصة. التبرير: تفكير يجعل السلوك الخاطئ يبدو مقبولًا. سيادة القانون: خضوع الجميع، بمن فيهم القادة، على قدم المساواة لقوانين عادلة ومعلنة. النزاهة الأكاديمية: التصرّف بأمانة وعدل ومسؤولية في التعلّم والتقييم. المُبلِّغ عن المخالفات: شخص يُبلغ عن المخالفات إلى الجهات القادرة على اتخاذ إجراء بشأنها.",
  intentions:["أن أفهم الاستراتيجيات الشخصية والمؤسسية والوطنية والدولية المستخدمة في مكافحة الفساد.","أن أحلّل دور الجهات الإماراتية والاتفاقيات الدولية في تعزيز المساءلة والشفافية.","أن أقيّم أكثر الاستراتيجيات فاعلية، وألتزم بأفعال شخصية ملموسة تعزّز النزاهة."],
  criteria:["أستطيع أن أشرح استراتيجيات مكافحة الفساد على المستويات الشخصية والمؤسسية والوطنية والدولية.","أستطيع أن أصف دور جهات المحاسبة الإماراتية واتفاقية الأمم المتحدة لمكافحة الفساد في مكافحة الفساد.","أستطيع أن أقيّم فاعلية مختلف الاستراتيجيات، وأضع التزامًا شخصيًا واقعيًا بالنزاهة."],
  concept:{key:"التغيير", related:"المساءلة، النزاهة", soi:"تتطلّب مكافحة الفساد مؤسسات قوية تُخضع السلطة للمساءلة، وأفرادًا يتحلّون بالشجاعة الأخلاقية للتصرّف بنزاهة.", context:"العدالة والتنمية: استكشاف كيف تبني المجتمعات مؤسسات شفافة وخاضعة للمساءلة ومواطنين يتحلّون بالأخلاق.", uae:"يتولّى جهاز الإمارات للمحاسبة (ديوان المحاسبة سابقًا) وجهاز أبوظبي للمحاسبة تدقيق الأموال العامة وتعزيز الشفافية؛ وقد صادقت دولة الإمارات على اتفاقية الأمم المتحدة لمكافحة الفساد عام 2006؛ ويُحتفى باليوم الدولي لمكافحة الفساد في 9 ديسمبر من كل عام."},
  words:[["الشفافية (Transparency)","الانفتاح بشأن القرارات والقواعد واستخدام الموارد، بحيث يستطيع الآخرون الاطّلاع عليها والتحقّق منها."],["المساءلة (Accountability)","الالتزام بتفسير القرارات والأفعال وتحمّل المسؤولية عنها."],["الرقابة (Oversight)","متابعة مؤسسة أو مسؤول والإشراف عليهما من قِبل جهة مستقلة."],["التدقيق (Audit)","فحص رسمي ومستقل لحسابات مؤسسة ما وأنشطتها."],["الشجاعة الأخلاقية (Moral courage)","الاستعداد لفعل الصواب رغم المخاطر أو الضغوط أو الاستنكار."],["النزاهة (Integrity)","الاتّساق بين المبادئ الأخلاقية للشخص وأفعاله، حتى عندما لا يراه أحد."]],
  task1:{title:"مهمة البحث", mins:20, criterion:"المعيار A — المعرفة والفهم", steps:["اختر جهة واحدة أو اتفاقية واحدة لمكافحة الفساد: جهاز الإمارات للمحاسبة، أو جهاز أبوظبي للمحاسبة، أو اتفاقية الأمم المتحدة لمكافحة الفساد، أو منظمة الشفافية الدولية.","ابحث فيها مستعينًا بمصدرين موثوقين على الأقل (مثل موقعها الرسمي، أو مكتب الأمم المتحدة المعني بالمخدرات والجريمة، أو مؤسسات إخبارية موثوقة).","سجّل: هدفها، والصلاحيات أو الأدوات التي تستخدمها، ومن تُخضعه للمساءلة.","قيّم عاملًا واحدًا يجعلها فعّالة، وعاملًا واحدًا يحدّ مما يمكنها تحقيقه."], prompts:["الجهة أو الاتفاقية التي اخترتها، ومصدراي","هدفها","الصلاحيات أو الأدوات التي تستخدمها، ومن تُخضعه للمساءلة","عامل واحد يجعلها فعّالة، وعامل واحد يحدّ منها"], success:"تميّز الإجابات القوية بوضوح بين أنواع الجهات الفاعلة: فأجهزة المحاسبة والتدقيق تفحص كيفية إنفاق المال العام؛ واتفاقية الأمم المتحدة لمكافحة الفساد معاهدة دولية تُلزم الدول بالوقاية والتجريم والتعاون الدولي واسترداد الأصول المسروقة؛ ومنظمة الشفافية الدولية منظمة غير حكومية تُجري البحوث وتنظّم الحملات. وللوصول إلى أعلى مستوى، استخدم المصادر الرسمية بدقة، وتجنّب الادعاءات غير المدعومة، وقيّم تقييمًا مدروسًا؛ فمثلًا يعتمد أثر جهاز التدقيق على استقلاليته وعلى ما إذا كانت نتائجه تؤدي إلى اتخاذ إجراءات."},
  task2:{title:"مهمة القراءة والكتابة", mins:25, criterion:"المعيار C — التواصل", extract:"يقول طالب في الصف الثالث عشر: «الفساد مشكلة على الحكومات والشركات الكبرى أن تحلّها. ولا يوجد ما يمكن لشخص عادي مثلي أن يفعله حيالها».", steps:["اكتب فقرة حجاجية منظّمة (أو فقرتين) تردّ فيها على هذا الادعاء، مستفيدًا مما تعلّمته في الوحدة الأولى كلها.","اعترف بدور المؤسسات، ثم دافع عن دور الفرد، مستخدمًا مثالين ملموسين على الأقل.","استخدم خمس كلمات على الأقل من بنوك كلمات الوحدة الأولى (من أي حصة) استخدامًا دقيقًا، واختم بالتزام شخصي واقعي واحد."], model:"صحيح أن المؤسسات، مثل جهاز الإمارات للمحاسبة والمحاكم والاتفاقيات الدولية كاتفاقية الأمم المتحدة لمكافحة الفساد، ضرورية، لأنها وحدها تملك صلاحية تدقيق الأموال العامة والتحقيق في المخالفات وملاحقة مرتكبيها قضائيًا. غير أن الادعاء بأن الأفراد لا يستطيعون فعل شيء يتجاهل الطريقة التي يعمل بها الفساد فعلًا. فكما يُظهر مثلث الاحتيال، يعتمد الفساد على التبرير، وكل شخص يرفض القبول بأن «الجميع يفعل ذلك» يُضعف التطبيع الذي يسمح للفساد بالانتشار. كما يمثّل الأفراد خط الدفاع الأول: فالطالب الذي يحافظ على النزاهة الأكاديمية، والموظف الذي يُفصح عن تضارب المصالح، والمُبلِّغ الذي يُبلغ عن الاحتيال عبر القنوات الصحيحة، يستطيعون إيقاف الضرر قبل أن تنتشر آثاره. لذا تتطلّب مكافحة الفساد رقابة قوية وشجاعة أخلاقية شخصية معًا. والتزامي هو أن أشير إلى كل مصدر وأداة أستخدمهما في أعمالي المقرّرة هذا العام، حتى عندما لا يلاحظ أحد إن لم أفعل.", rubric:[["1–2","تنظيم محدود؛ قبول الادعاء أو رفضه دون تعليل؛ مفردات قليلة."],["3–4","تنظيم أساسي؛ بعض التعليل؛ مثال واحد؛ استخدام 2–3 مصطلحات أساسية."],["5–6","بنية حجاجية واضحة؛ الاعتراف بدور المؤسسات؛ مثالان ملموسان؛ استخدام 4 مصطلحات أساسية؛ التزام واقعي."],["7–8","حجّة متقنة ومحكمة البناء تستفيد من حصص عدة؛ استخدام 5 مصطلحات أساسية أو أكثر بدقة؛ أمثلة عميقة؛ التزام محدّد وصادق."]], starters:["صحيح أن المؤسسات، مثل ___، ضرورية لأن ___.","غير أن الادعاء بأن الأفراد لا يستطيعون فعل شيء يتجاهل ___.","فمثلًا، الطالب / الموظف الذي ___ يستطيع أن ___.","التزامي الشخصي هو أن ___."]},
  task3:{title:"مهمة المشروع (عرض الوحدة)", mins:"حصتان", criterion:"المعيار D — التفكير الناقد", name:"حملة اليوم الدولي لمكافحة الفساد", steps:["في مجموعات من 3 إلى 4 طلاب، صمّموا حملة مدرسية بمناسبة اليوم الدولي لمكافحة الفساد (9 ديسمبر)، موجّهة إلى الطلاب الأصغر سنًّا في المرحلة الثانوية.","اختاروا محورًا واحدًا من الوحدة الأولى (مثل النزاهة الأكاديمية والذكاء الاصطناعي، أو الضحايا الخفيين للفساد، أو رفض الرشاوى «الصغيرة»، أو التحدّث بأمان).","أعدّوا حزمة حملة تتضمّن: رسالة رئيسة، وملصقًا أو نصّ فيديو قصير، ونشاطًا تفاعليًا واحدًا يناسب صفًا أصغر سنًّا.","اشرحوا كيف ستقيسون ما إذا كانت حملتكم قد غيّرت المواقف (مثل استبانة قبل الحملة وبعدها).","اعرضوا حملتكم على الصف في 5 دقائق، وقد تُشارَك أقوى حملة مع فريق القيادة الطلابية في المدرسة. استخدموا مفردات بنوك الكلمات من الوحدة الأولى كلها."], rubric:[["1–2","رسالة الحملة غير واضحة؛ ارتباط ضعيف بتعلّم الوحدة؛ لا توجد خطة للتقييم."],["3–4","حملة أساسية ترتبط ببعض تعلّم الوحدة؛ النشاط أو خطة التقييم غير مكتملين."],["5–6","حملة واضحة ومناسبة للفئة العمرية ترتبط بقوة بتعلّم الوحدة؛ نشاط جاذب؛ خطة تقييم منطقية."],["7–8","حملة مقنعة ومبتكرة وواقعية تستفيد من حصص عدة؛ نشاط جاذب للغاية؛ خطة تقييم مدروسة وقابلة للقياس."]]},
  game:{type:"sort", title:"ما مستوى الفعل؟", prompt:"صنّف كل إجراء لمكافحة الفساد وفق المستوى الذي يعمل عليه.", bins:["النزاهة الشخصية","ضمانة مؤسسية / وطنية","التعاون الدولي"], items:[["رفض مشاركة عملك المقرّر مع صديق لينقله",0],["جهاز محاسبة يدقّق في كيفية إنفاق وزارة ما للأموال العامة",1],["دول تتعاون لاسترداد أصول مسروقة مُخبّأة في الخارج",2],["الإفصاح عن تضارب المصالح قبل اتخاذ قرار",0],["شركة تُنشئ خطًا ساخنًا سرّيًا للإبلاغ عن المخالفات",1],["دول تلتزم باتفاقية الأمم المتحدة لمكافحة الفساد",2],["تحويل الخدمات الحكومية إلى خدمات إلكترونية للحدّ من «مدفوعات التسريع» وجهًا لوجه",1],["قول «لا» عندما يقول زميل «الجميع يفعل ذلك»",0]]},
  quiz:[["ماذا تعني «الشفافية» في مكافحة الفساد؟",["الانفتاح بشأن القرارات واستخدام الموارد، بحيث يستطيع الآخرون التحقّق منها","إبقاء جميع القرارات سرّية","اتخاذ القرارات بسرعة كبيرة"],0],["ما الدور الرئيس لجهاز الإمارات للمحاسبة؟",["تأليف الكتب المدرسية","تدقيق الأموال العامة وتعزيز المساءلة والشفافية","إدارة الشركات الخاصة"],1],["متى يُحتفى باليوم الدولي لمكافحة الفساد كل عام؟",["1 يناير","2 ديسمبر","9 ديسمبر"],2],["ما اتفاقية الأمم المتحدة لمكافحة الفساد؟",["شركة إماراتية","معاهدة دولية تُلزم الدول بمنع الفساد ومكافحته","نوع من التدقيق"],1],["لماذا يقلّل تحويل الخدمات الحكومية إلى خدمات إلكترونية من مخاطر الفساد؟",["لأنه يحدّ من السلطة التقديرية في التعامل وجهًا لوجه ويوفّر سجلات واضحة","لأنه يزيد دخل الموظفين","لأنه يُلغي جميع القواعد"],0],["أيّ مما يأتي مثال على الشجاعة الأخلاقية؟",["مجاراة الآخرين لتجنّب المشكلات","تجاهل مخالفة تلاحظها","الإبلاغ عن المخالفات عبر القنوات الصحيحة رغم الضغوط لالتزام الصمت"],2],["لماذا يُعدّ الفرد مهمًا في مكافحة الفساد، وفقًا لهذه الوحدة؟",["لأن الأفراد لا يستطيعون إحداث أي فرق","لأن رفض تبرير الخطأ أو تطبيعه يوقف انتشار الفساد","لأن الحكومات وحدها قادرة على التعرّف إلى الفساد"],1],["أيّ العبارات الآتية تلخّص الوحدة الأولى على أفضل وجه؟",["الفساد مسألة قانونية تخصّ الحكومات فقط","الأخلاق تقتصر على اتّباع القواعد المدرسية","مكافحة الفساد تحتاج إلى مؤسسات قوية وأفراد يتحلّون بالنزاهة"],2]],
  exit:"اكتب التزامًا واحدًا محدّدًا وواقعيًا ستلتزم به هذا العام للتصرّف بنزاهة، واشرح سبب أهميته.",
  copy:{facts:["يُكافَح الفساد على أربعة مستويات: النزاهة الشخصية، والضمانات المؤسسية، والجهات الوطنية، والتعاون الدولي.","يتولّى جهاز الإمارات للمحاسبة وجهاز أبوظبي للمحاسبة تدقيق الأموال العامة؛ وقد صادقت دولة الإمارات على اتفاقية الأمم المتحدة لمكافحة الفساد عام 2006؛ ويوافق اليوم الدولي لمكافحة الفساد 9 ديسمبر.","تقلّل الشفافية والمساءلة والرقابة المستقلة من فرص الفساد، في حين تتصدّى الشجاعة الأخلاقية الفردية للتبرير والتطبيع."]},
  next:"اكتملت الوحدة الأولى: الأخلاق في حياتنا المعاصرة! وفي الحصص القادمة، نبدأ الوحدة التالية من مقرّر التربية الأخلاقية للصف الثاني عشر."
 }
];
